import {BAITS,LINES,effectiveRod,fishWeight,rollFish} from './economy.js?v=5';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function worldConditions(now=Date.now(),region=0){const cycle=(now%1200000)/1200000,phase=cycle<.12?'dawn':cycle<.51?'day':cycle<.64?'dusk':'night';const bucket=Math.floor(now/300000),h=Math.abs(Math.sin(bucket*127.1+region*31.7)*43758.5453)%1,weather=h<.45?'clear':h<.69?'mist':h<.88?'rain':'wind';const moon=(Math.floor(now/86400000)%8)/8;const rarity=(phase==='dawn'||phase==='dusk'?1.22:phase==='night'?1.12:1)*(weather==='rain'&&region<3?1.18:weather==='mist'?1.08:1)*(moon>.3&&moon<.7?1.08:1);return {cycle,phase,weather,moon,rarity,bite:weather==='wind'?.83:weather==='rain'?1.12:1,swell:region>=3?(weather==='wind'?1.4:1):.2};}
export function startEncounter(s,conditions,rng=Math.random){let bait=BAITS[s.bait]||BAITS[0];if(!s.ownedBaits.includes(bait.id)){s.bait=0;bait=BAITS[0];}const fish=rollFish(s,rng,conditions);s.attempts++;s.activeCast=true;s.rodCondition=Math.max(0,s.rodCondition-(s.rodBroken?0:.18));const bites=rng()<Math.min(.98,bait.bite*conditions.bite);const weight=fishWeight(fish),spPower=.7+Math.sqrt(weight)*1.1;return {fish,bites,bait:bait.id,progress:0,tension:.24,slack:0,misses:0,elapsed:0,overload:0,weight,power:spPower,outcome:null,pulls:0,environment:conditions,held:false};}
export function reelProfile(rarity=0){const r=clamp(Math.floor(rarity),0,4);return {width:[.68,.50,.34,.22,.12][r],speed:[.00105,.0016,.0022,.0031,.0042][r]};}
export function isReelHit(fight,accuracy){return Math.abs(accuracy-.5)<=reelProfile(fight.rarity).width/2;}
export function setFishPower(fight,rarity){fight.rarity=rarity;fight.power+=rarity*.8;return fight;}
export function stepFight(fight,s,dt){if(fight.outcome)return fight.outcome;dt=clamp(dt,0,.1);fight.elapsed+=dt;const rod=effectiveRod(s),line=LINES[s.line],ratio=fight.power/Math.min(rod.power,line.power);fight.tension=clamp(fight.tension+((ratio>1?(ratio-1)*.027:0)-.035)*dt,.08,1.2);fight.slack+=dt*.014;fight.overload=fight.tension>.91?fight.overload+dt:Math.max(0,fight.overload-dt*.7);if(fight.overload>1.7){fight.outcome=rod.power<line.power&&s.rod>0&&!s.rodBroken?'rod-snap':'line-snap';}else if(fight.slack>1||fight.elapsed>48||fight.misses>=4)fight.outcome='escaped';return fight.outcome;}
export function reelPull(fight,s,accuracy){if(fight.outcome)return fight.outcome;const ratio=fight.power/Math.min(effectiveRod(s).power,LINES[s.line].power);fight.pulls++;const hit=isReelHit(fight,accuracy);if(hit){fight.slack=Math.max(0,fight.slack-.16);fight.progress+=.24/Math.max(.85,ratio);fight.tension+=.07+Math.max(0,ratio-1)*.17;}else{fight.misses++;fight.progress=Math.max(0,fight.progress-.035);fight.tension+=.19+Math.max(0,ratio-1)*.12;fight.slack+=.13;}if(s.rod>0&&!s.rodBroken){s.rodCondition=Math.max(0,s.rodCondition-(hit?.25:.9));if(s.rodCondition<=0){fight.outcome='rod-snap';return fight.outcome;}}if(ratio>1.1)fight.progress=Math.min(.82,fight.progress);if(fight.tension>=1.06)fight.outcome=effectiveRod(s).power<LINES[s.line].power&&s.rod>0&&!s.rodBroken?'rod-snap':'line-snap';else if(fight.misses>=4)fight.outcome='escaped';else if(fight.progress>=1&&ratio<=1.1)fight.outcome='caught';return fight.outcome;}
export function resolveFailure(s,reason){s.activeCast=false;if(reason==='rod-snap'){s.rodBroken=true;s.rodCondition=0;}else if(reason==='line-snap'){s.rodCondition=Math.max(0,s.rodCondition-8);if(s.line>0){const cost=Math.max(6,Math.ceil(LINES[s.line].cost*.06));if(s.pearls>=cost)s.pearls-=cost;else s.line=0;}}else s.rodCondition=Math.max(0,s.rodCondition-2);if(s.rodCondition<=0&&s.rod>0)s.rodBroken=true;}
